spec.expr:
gwm_http_endpoint_up{
    $cluster_label=~"$cluster",
    protocol="$protocol",
    hostname=~"$httproute_hostname",
    port="$port"
}

gwm_http_endpoint_trust{
    $cluster_label=~"$cluster",
    protocol="$protocol",
    hostname=~"$httproute_hostname",
    port="$port"
}

gwm_http_endpoint_not_before{
    $cluster_label=~"$cluster",
    protocol="$protocol",
    hostname=~"$httproute_hostname",
    port="$port"
}* 1000

avg(
  histogram_quantile(
      0.50, 
      sum(
          rate(
              gwm_tls_endpoint_response_time_millis_bucket{
                  $cluster_label=~"$cluster",
                  hostname=~"$hostname"
              }[$interval]
          )
      ) by (le, protocol, hostname, port)
  ) * on(protocol, hostname, port) (
      gwm_tls_endpoint_up == 1
  )
)

