label_replace(
    label_join(
        (
            sum by (protocol, port, hostname) (
                rate(gwm_http_endpoint_response_time_millis_sum{$cluster_label=~"$cluster"}[$interval]) < Inf
            ) /
            sum by (protocol, port, hostname) (
                rate(gwm_http_endpoint_response_time_millis_count{$cluster_label=~"$cluster"}[$interval]) < Inf
            )
        ) or
        (
            label_replace(
                sum by (protocol, port, hostname) (
                    rate(gwm_tls_endpoint_response_time_millis_sum{$cluster_label=~"$cluster"}[$interval]) < Inf
                )
                /
                sum by (protocol, port, hostname) (
                    rate(gwm_tls_endpoint_response_time_millis_count{$cluster_label=~"$cluster"}[$interval]) < Inf
                ),
                "protocol", "tls", "", ".*"
            )
        ),
        "Endpoint", ";", "protocol", "hostname", "port"
    ), "Endpoint", "$1://$2:$3", "Endpoint", "([^;]+);([^;]+);([^;]+)"
)

# -1 if error, 0 if down, 1 if up
sum by (protocol, port, hostname) (
    -1 * (gwm_http_endpoint_error{$cluster_label=~"$cluster"} == 1)
    or gwm_http_endpoint_up{$cluster_label=~"$cluster"}
    or label_replace(
        -1 * (gwm_tls_endpoint_error{$cluster_label=~"$cluster"} == 1)
        or gwm_tls_endpoint_up{$cluster_label=~"$cluster"}
        ,"protocol", "tls", "", ".*"
